type AssistantPhase = 'idle' | 'listening' | 'thinking' | 'speaking';

interface SearchFilters {
  category: string | null;
  size: string | null;
  color: string | null;
  priceMin: number | null;
  priceMax: number | null;
  inStockOnly: boolean;
  query: string | null;
}

type FilterKey = keyof SearchFilters;
type FacetKey = 'category' | 'size' | 'color';

interface FilterPatch {
  set: Partial<{ [K in FilterKey]: NonNullable<SearchFilters[K]> }>;
  clear: Exclude<FilterKey, 'inStockOnly'>[];
}

interface ProductCard {
  productId: string;
  name: string;
  price: number;
  currency: string;
  inStock: boolean;
  url: string;
  imageUrl: string;
}

type AbortReason = 'cancel' | 'timeout';

interface Turn {
  turnId: string;
  mode: 'voice' | 'text' | 'direct';
  text: string;
  draft: SearchFilters | null;
  controller: AbortController;
}

interface Choice {
  about: FacetKey;
  options: string[];
  pending: FilterPatch | null;
}

type AssistantProblem =
  | 'mic-denied'
  | 'no-mic'
  | 'mic-busy'
  | 'nothing-heard'
  | 'not-understood'
  | 'out-of-scope'
  | 'no-results'
  | 'timeout'
  | 'connection-lost';

interface ConversationState {
  phase: AssistantPhase;
  consent: 'unknown' | 'given' | 'declined';
  mic: 'unknown' | 'ready' | 'denied' | 'missing';
  partialText: string;
  textBox: string;
  activeTurn: Turn | null;
  filters: SearchFilters;
  undo: SearchFilters | null;
  results: ProductCard[];
  total: number;
  summary: string | null;
  choice: Choice | null;
  problem: AssistantProblem | null;
  speakReplies: boolean;
}
